import flash.display.StageScaleMode;
import flash.display.StageAlign;
import flash.events.Event;
import flash.events.MouseEvent;
import flash.text.TextFieldAutoSize; // WAJIB ADA: Biar teks skor bisa rata kanan
import flash.utils.setTimeout;      // WAJIB ADA: Biar kode setTimeout jalan
import flash.display.MovieClip;

// 1. Setup Layar
stop();
stage.align = StageAlign.TOP_LEFT;
stage.scaleMode = StageScaleMode.SHOW_ALL;

// --- DATABASE SOAL ---
// Pastikan tidak redeclare jika frame dimuat ulang
var bankSoal:Array = [
	{t: "Logam mulia yang tahan karat dan sering dijadikan investasi adalah...", j: ["Perak", "Tembaga", "Timah", "Emas"], b: 3},
	{t: "Apa nama bijih utama pembentuk Aluminium?", j: ["Hematit", "Bauksit", "Limonit", "Kuarsa"], b: 1},
	{t: "Mineral bahan utama baterai kendaraan listrik?", j: ["Nikel", "Bauksit", "Batubara", "Emas"], b: 0},
	{t: "Daerah penghasil Timah terbesar di Indonesia?", j: ["Papua", "Kaltim", "Bangka Belitung", "Sulteng"], b: 2},
	{t: "Morowali terkenal dengan tambang...", j: ["Nikel", "Emas", "Intan", "Minyak"], b: 0}
];

var skor:int = 0;
var indexSoal:int = 0;
var totalSoal:int = bankSoal.length;
var sedangMenjawab:Boolean = false;

// --- INIT ---
initGame();

function initGame():void {
	skor = 0;
	indexSoal = 0;

	// Setup text
	if(getChildByName("txt_soal")) { 
		Object(getChildByName("txt_soal")).wordWrap = true; 
		Object(getChildByName("txt_soal")).multiline = true;
	}
	if(getChildByName("txt_skor")) Object(getChildByName("txt_skor")).autoSize = TextFieldAutoSize.RIGHT;
	if(getChildByName("txt_progress")) Object(getChildByName("txt_progress")).autoSize = TextFieldAutoSize.LEFT;

	// Setup Tombol (Looping 4 tombol: btn_jawab0 sampai btn_jawab3)
	for(var i:int = 0; i < 4; i++){
		// Mengambil tombol berdasarkan nama string
		var btn:MovieClip = getChildByName("btn_jawab" + i) as MovieClip;

		if(btn){
			btn.id = i; // Menyimpan nomor ID ke dalam tombol
			btn.buttonMode = true; 
			btn.mouseChildren = false; 

			// Hapus listener lama biar tidak dobel saat restart
			if(btn.hasEventListener(MouseEvent.CLICK)) btn.removeEventListener(MouseEvent.CLICK, cekJawaban);
			btn.addEventListener(MouseEvent.CLICK, cekJawaban);
		} else {
			trace("PERINGATAN: btn_jawab" + i + " tidak ditemukan di Stage!");
		}
	}
	tampilkanSoal();
}

function tampilkanSoal():void {
	// Cek apakah soal sudah habis
	if(indexSoal >= totalSoal){
		pergiKeHasil();
		return;
	}

	sedangMenjawab = false;
	var data:Object = bankSoal[indexSoal];

	// 1. Update Teks Soal
	if(getChildByName("txt_soal")) Object(getChildByName("txt_soal")).text = data.t;

	// 2. Update Skor
	if(getChildByName("txt_skor")) Object(getChildByName("txt_skor")).text = "Skor: " + skor;

	// 3. Update Progress
	if(getChildByName("txt_progress")) Object(getChildByName("txt_progress")).text = "Pertanyaan " + (indexSoal + 1) + "/" + totalSoal;

	// 4. Update Bar Time (Garis Merah)
	if(getChildByName("bar_time")) Object(getChildByName("bar_time")).scaleX = (indexSoal + 1) / totalSoal;

	// 5. Update Label Tombol
	for(var i:int = 0; i < 4; i++){
		var btn:MovieClip = getChildByName("btn_jawab" + i) as MovieClip;
		if(btn){
			btn.gotoAndStop(1); // Kembali ke frame awal (netral)

			// --- BAGIAN KRUSIAL: MENGGANTI TEKS TOMBOL ---
			// Kita cari teks di dalam tombol secara manual agar aman
			if(btn.getChildByName("txt_label")){
				Object(btn.getChildByName("txt_label")).text = data.j[i];
			} else {
				trace("ERROR: txt_label tidak ditemukan di dalam btn_jawab" + i);
			}
		}
	}
}

function cekJawaban(e:MouseEvent):void {
	if(sedangMenjawab) return;
	sedangMenjawab = true;

	var btnKlik:MovieClip = e.currentTarget as MovieClip;
	var jawabanUser:int = btnKlik.id;
	var kunci:int = bankSoal[indexSoal].b;

	if(jawabanUser == kunci){
		skor += 20;
		btnKlik.gotoAndStop(2); // Frame 2 = Benar (Hijau)
	} else {
		btnKlik.gotoAndStop(3); // Frame 3 = Salah (Merah)

		// Cari tombol yang benar untuk dikasih tahu ke user
		var btnBenar:MovieClip = getChildByName("btn_jawab" + kunci) as MovieClip;
		if(btnBenar) btnBenar.gotoAndStop(2);
	}

	// Update skor langsung
	if(getChildByName("txt_skor")) Object(getChildByName("txt_skor")).text = "Skor: " + skor;

	// Pindah soal setelah 1.5 detik
	setTimeout(nextSoal, 1500);
}

function nextSoal():void {
	indexSoal++;
	tampilkanSoal();
}

function pergiKeHasil():void {
	// Simpan skor ke variabel global (root) agar bisa dibaca di halaman hasil
	MovieClip(root).skorFinal = skor;

	// Hapus listener agar memori bersih
	for(var i:int = 0; i < 4; i++){
		var btn:MovieClip = getChildByName("btn_jawab" + i) as MovieClip;
		if(btn && btn.hasEventListener(MouseEvent.CLICK)) {
			btn.removeEventListener(MouseEvent.CLICK, cekJawaban);
		}
	}

	// Pindah ke halaman hasil (Frame 20)
	gotoAndStop(20);
}

import flash.display.StageScaleMode;
import flash.display.StageAlign;
import flash.events.Event;
import flash.events.MouseEvent;
import flash.display.MovieClip;

stop();
stage.align = StageAlign.TOP_LEFT;
stage.scaleMode = StageScaleMode.SHOW_ALL;

// Ambil skor dari variabel global yang kita simpan tadi
var nilaiAkhir:int = 0;
if(MovieClip(root).skorFinal != undefined){
	nilaiAkhir = MovieClip(root).skorFinal;
}

// Tampilkan ke teks
if(getChildByName("txt_finalskor")){
	Object(getChildByName("txt_finalskor")).text = String(nilaiAkhir);
}

// Tombol Coba Lagi (Reset ke Halaman Awal Kuis - Frame 18)
if(getChildByName("btn_cobalagi")){
	// Hapus listener lama dulu biar aman
	if(btn_cobalagi.hasEventListener(MouseEvent.CLICK)) btn_cobalagi.removeEventListener(MouseEvent.CLICK, ulangKuis);

	btn_cobalagi.addEventListener(MouseEvent.CLICK, ulangKuis);
}

function ulangKuis(e:MouseEvent):void{
	gotoAndStop(18); // Ke halaman "Tantangan Selayang Pandang"
}

// Tombol Kembali (Ke Materi - Frame 17)
if(getChildByName("btn_kembali")){
	btn_kembali.addEventListener(MouseEvent.CLICK, function(e:MouseEvent):void{ 
		gotoAndStop(17); 
	});
}

